import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Armor and protection","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/armor-and-protection.md","filePath":"en/guide/combat/armor-and-protection.md"}'),n={name:"en/guide/combat/armor-and-protection.md"};function o(d,e,l,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="armor-and-protection" tabindex="-1">Armor and protection <a class="header-anchor" href="#armor-and-protection" aria-label="Permalink to &quot;Armor and protection&quot;">​</a></h1><p><strong>Status:</strong> Accepted coverage and shared-item wear · Experimental protection partly integrated · Proposed material interactions.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Protection depends on the body region actually struck.</li><li>Sleeves and leggings remain shared items with shared durability.</li><li>Material, condition and maintenance should create choices; the expanded material model is not implemented.</li></ul><p><span id="protection-depends-on-where-the-hit-lands"></span><span id="materials-and-condition"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Coverage</td><td>An uncovered region stays uncovered; the hit is not moved elsewhere to find armor.</td></tr><tr><td>Shared pieces</td><td>Sleeves cover both arms and leggings both legs, without separate left/right item durability.</td></tr><tr><td>Materials</td><td>Plate, mail, leather and padding may trade protection against burden, mobility and transmitted impact. Exact matchups remain unresolved.</td></tr><tr><td>Maintenance</td><td>Repair expertise and quality should help retain function, without removing equipment-loss risk.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>UOR armor already trades protection against penalties</td><td>Explore coverage, condition and physical interaction in more detail.</td></tr><tr><td>Armor can wear during combat</td><td>Keep equipment durability distinct from the wearer’s local injury.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A blow lands on an armored arm. The sleeve’s condition and the arm’s integrity are separate concerns; repairing the sleeve is not medical treatment.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/limbs-and-trauma.html">Limbs and Trauma</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item quality</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">Read the full design specification</a></p>',15)])])}const u=t(n,[["render",o]]);export{p as __pageData,u as default};
